          </div>
        </div>
        <aside className="z-[5] flex w-[380px] min-w-[380px] flex-none flex-col border-l bg-card max-[900px]:w-full max-[900px]:min-w-0 max-[900px]:border-t max-[900px]:border-l-0" aria-label="Thiết lập ký">
